            modelBuilder.Entity("AgriForecast.Domain.Entities.ForecastSnapshot", b =>
                {
                    b.Property<Guid>("Id")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("uniqueidentifier");

                    b.Property<decimal?>("AbsoluteError")
                        .HasPrecision(10, 2)
                        .HasColumnType("decimal(10,2)");

                    b.Property<string>("ActivePredictor")
                        .IsRequired()
                        .HasMaxLength(50)
                        .HasColumnType("nvarchar(50)");

                    b.Property<DateOnly?>("ActualObservedDate")
                        .HasColumnType("date");

                    b.Property<decimal?>("ActualPrice")
                        .HasPrecision(10, 2)
                        .HasColumnType("decimal(10,2)");

                    b.Property<string>("Confidence")
                        .IsRequired()
                        .HasMaxLength(20)
                        .HasColumnType("nvarchar(20)");

                    b.Property<DateTime>("CreatedAtUtc")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("datetime2")
                        .HasDefaultValueSql("SYSUTCDATETIME()");

                    b.Property<Guid>("CropId")
                        .HasColumnType("uniqueidentifier");

                    b.Property<string>("FallbackTier")
                        .HasMaxLength(50)
                        .HasColumnType("nvarchar(50)");

                    b.Property<int?>("GrowthPeriodDays")
                        .HasColumnType("int");

                    b.Property<DateOnly?>("HarvestDate")
                        .HasColumnType("date");

                    b.Property<decimal>("LowerBound")
                        .HasPrecision(10, 2)
                        .HasColumnType("decimal(10,2)");

                    b.Property<DateTime?>("MaturedAtUtc")
                        .HasColumnType("datetime2");

                    b.Property<string>("MaturityState")
                        .IsRequired()
                        .HasMaxLength(30)
                        .HasColumnType("nvarchar(30)");

                    b.Property<string>("ModelVersion")
                        .HasMaxLength(20)
                        .HasColumnType("nvarchar(20)");

                    b.Property<decimal?>("PercentageError")
                        .HasPrecision(9, 4)
                        .HasColumnType("decimal(9,4)");

                    b.Property<decimal>("PredictedPrice")
                        .HasPrecision(10, 2)
                        .HasColumnType("decimal(10,2)");

                    b.Property<string>("ReasonCode")
                        .HasMaxLength(100)
                        .HasColumnType("nvarchar(100)");

                    b.Property<decimal?>("ReferencePrice")
                        .HasPrecision(10, 2)
                        .HasColumnType("decimal(10,2)");

                    b.Property<decimal?>("SignedError")
                        .HasPrecision(10, 2)
                        .HasColumnType("decimal(10,2)");

                    b.Property<DateOnly>("SnapshotDate")
                        .HasColumnType("date");

                    b.Property<decimal>("UpperBound")
                        .HasPrecision(10, 2)
                        .HasColumnType("decimal(10,2)");

                    b.Property<bool?>("WithinInterval")
                        .HasColumnType("bit");

                    b.HasKey("Id");

                    b.HasIndex(new[] { "CropId", "SnapshotDate" }, "IX_ForecastSnapshots_CropSnapshotDateDesc")
                        .IsDescending(false, true);

                    b.HasIndex(new[] { "HarvestDate" }, "IX_ForecastSnapshots_HarvestDatePending")
                        .HasFilter("[MaturityState] = 'pending'");

                    b.HasIndex(new[] { "CropId", "SnapshotDate" }, "UX_ForecastSnapshots_CropSnapshotDate")
                        .IsUnique();

                    b.ToTable("ForecastSnapshots", t =>
                        {
                            t.HasCheckConstraint("CK_ForecastSnapshots_Band", "[UpperBound] >= [LowerBound] AND [LowerBound] >= 0");

                            t.HasCheckConstraint("CK_ForecastSnapshots_MaturityState", "[MaturityState] COLLATE Latin1_General_BIN2 IN ('pending', 'matured', 'actual_unavailable', 'not_maturable')");
                        });
                });

